const translationsAlt = {
    es: {
        "heroTitleAlt": "Mantengámonos jóvenes y saludables"
    },
    en: {
        "heroTitleAlt": "Let's Stay Young and Healthy"
    }
};

function getTranslatedText(key, lang) {
    const text = translations[lang] && translations[lang][key] ? translations[lang][key] : (translations.es[key] || key);
    
    if (text.includes('{liters}') || text.includes('{glasses}')) {
        return text;
    }
    
    return text;
}

function detectBrowserLanguage() {
    const browserLang = navigator.language || navigator.userLanguage;
    const lang = browserLang ? browserLang.split('-')[0] : 'es';
    return (lang === 'en') ? 'en' : 'es';
}

function getCurrentLanguage() {
    const stored = localStorage.getItem('preferredLanguage');
    if (stored) return stored;
    return detectBrowserLanguage();
}

function setLanguage(lang) {
    localStorage.setItem('preferredLanguage', lang);
    document.documentElement.lang = lang;
    updateAllContent(lang);
}

function updateAllContent(lang) {
    const elements = document.querySelectorAll('[data-i18n]');
    elements.forEach(el => {
        const key = el.getAttribute('data-i18n');
        const text = getTranslatedText(key, lang);
        if (text) el.textContent = text;
    });
    
    const titleElement = document.querySelector('title');
    if (titleElement && titleElement.hasAttribute('data-i18n-title')) {
        const key = titleElement.getAttribute('data-i18n-title');
        titleElement.textContent = getTranslatedText(key, lang);
    }
    
    const placeholders = document.querySelectorAll('[data-i18n-placeholder]');
    placeholders.forEach(el => {
        const key = el.getAttribute('data-i18n-placeholder');
        el.setAttribute('placeholder', getTranslatedText(key, lang));
    });
    
    updateLanguageButton(lang);
}

function updateLanguageButton(lang) {
    const btn = document.getElementById('languageToggle');
    if (btn) {
        btn.textContent = lang === 'es' ? 'English' : 'Español';
        btn.setAttribute('title', lang === 'es' ? 'Switch to English' : 'Cambiar a Español');
    }
}

function initLanguage(lang) {
    document.documentElement.lang = lang;
    updateAllContent(lang);
}

document.addEventListener('DOMContentLoaded', function() {
    const lang = getCurrentLanguage();
    initLanguage(lang);
    
    const btn = document.getElementById('languageToggle');
    if (btn) {
        btn.addEventListener('click', function() {
            const currentLang = getCurrentLanguage();
            const newLang = currentLang === 'es' ? 'en' : 'es';
            setLanguage(newLang);
        });
    }
});
